/** 使用真实指针拖动三块区域，验证布局调整不改变跟随状态和详情内容。 */
import assert from 'node:assert/strict';
import { mkdir, writeFile } from 'node:fs/promises';
export async function runRegions(page, artifactDir) {
  const checks=[];
  const check=(name,condition)=>{assert.ok(condition,name);checks.push(name);};
  const settle=()=>page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));
  const size=()=>page.evaluate(()=>Object.fromEntries(['.cx-overview-pane','.cx-flow-chart','.cx-work','.cx-ledger','.cx-inspector','.cx-panel','.cx-footer'].map(selector=>[selector,document.querySelector(selector).getBoundingClientRect().toJSON()])));
  const center=selector=>page.evaluate(s=>{const r=document.querySelector(s).getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2};},selector);
  const drag=async(selector,dx,dy,cancel=false)=>{const p=await center(selector);await page.mouse.move(p.x,p.y);await page.mouse.down();await page.mouse.move(p.x+dx,p.y+dy,{steps:6,label:'调整区域大小'});if(cancel){await page.keyboard.press('Tab');await page.keyboard.press('Escape');}await page.mouse.up();await settle();};
  const close=(a,b)=>Math.abs(a-b)<2;
  const followed=()=>page.evaluate(()=>{const e=document.querySelector('.cx-scroll');return window.readerFixture.state().view.follow==='following'&&Math.abs(e.scrollTop-(e.scrollHeight-e.clientHeight))<3;});
  const shot=async name=>{const viewport=await page.evaluate(()=>({width:Math.ceil(innerWidth*devicePixelRatio),height:Math.ceil(innerHeight*devicePixelRatio)}));const r=await page.cdp('Page.captureScreenshot',{format:'png',captureBeyondViewport:true,clip:{x:0,y:0,...viewport,scale:1}});await writeFile(`${artifactDir}/${name}.png`,Buffer.from(r.data,'base64'));};
  await mkdir(artifactDir,{recursive:true});await page.reload();await page.click('text="English"');
  await page.evaluate(()=>{window.readerFixture.setUiStyle('classic');document.documentElement.dataset.theme='light';});await settle();
  const initial=await size();
  check('Initial list follows latest records',await followed());
  await drag('.cx-overview-resizer',0,50);
  const taller=await size();
  check('Vertical drag grows overview and chart while shrinking records and details',close(taller['.cx-overview-pane'].height,initial['.cx-overview-pane'].height+50)&&close(taller['.cx-work'].height,initial['.cx-work'].height-50)&&taller['.cx-flow-chart'].height>initial['.cx-flow-chart'].height+40);
  check('Shrinking the list preserves following and bottom position',await followed());
  await drag('.cx-overview-resizer',0,-100);
  check('Growing the list does not mistake scroll clamping for user reading',await followed());
  const beforeWidth=await size();await drag('.cx-inspector-resizer',-150,0);const wider=await size();
  check('Horizontal drag exchanges width between records and details',close(wider['.cx-inspector'].width,beforeWidth['.cx-inspector'].width+150)&&close(wider['.cx-ledger'].width,beforeWidth['.cx-ledger'].width-150));
  check('Horizontal resize keeps the overview height',close(wider['.cx-overview-pane'].height,beforeWidth['.cx-overview-pane'].height));
  await page.press('.cx-inspector-resizer','Shift+ArrowRight');await page.press('.cx-inspector-resizer','ArrowLeft');await settle();
  check('Horizontal separator supports normal and accelerated keyboard steps',close((await size())['.cx-inspector'].width,wider['.cx-inspector'].width-40));
  const beforeCancel=await size();await drag('.cx-overview-resizer',0,45,true);await drag('.cx-inspector-resizer',-45,0,true);
  const cancelled=await size();
  check('Escape after moving focus rolls back both drag gestures',close(cancelled['.cx-overview-pane'].height,beforeCancel['.cx-overview-pane'].height)&&close(cancelled['.cx-inspector'].width,beforeCancel['.cx-inspector'].width));
  check('Cancelling a drag leaves details selected',await page.evaluate(()=>!!document.querySelector('.cx-inspector')&&window.readerFixture.state().view.selectedEventId==='context'));
  await page.press('.cx-overview-resizer','ArrowDown');await page.press('.cx-overview-resizer','Shift+ArrowDown');await settle();
  check('Vertical separator supports normal and accelerated keyboard steps',close((await size())['.cx-overview-pane'].height,beforeCancel['.cx-overview-pane'].height+60));
  await page.dblclick('.cx-overview-resizer');await page.dblclick('.cx-inspector-resizer');await settle();
  check('Double click restores default heights and widths',close((await size())['.cx-overview-pane'].height,248)&&close((await size())['.cx-inspector'].width,330));
  await page.press('.cx-overview-resizer','Home');
  check('Home stops at minimum overview size',await page.evaluate(()=>{const e=document.querySelector('.cx-overview-resizer');return e.getAttribute('aria-valuenow')===e.getAttribute('aria-valuemin');}));
  await page.press('.cx-overview-resizer','End');
  check('End reserves usable records space',await page.evaluate(()=>document.querySelector('.cx-work').clientHeight>=139));
  await page.press('.cx-overview-resizer','Enter');await page.press('.cx-inspector-resizer','ArrowLeft');await settle();
  const preserved=await size();
  await page.selectOption('select[aria-label="Fixture"]','command');await page.selectOption('select[aria-label="Fixture"]','context');await page.evaluate(()=>window.readerFixture.refresh());await settle();
  check('Entry switching and live updates retain chosen dimensions',close((await size())['.cx-overview-pane'].height,preserved['.cx-overview-pane'].height)&&close((await size())['.cx-inspector'].width,preserved['.cx-inspector'].width));
  await page.evaluate(()=>{document.querySelector('.cx-detail-body').scrollTop=450;});await settle();const scroll=await page.evaluate(()=>document.querySelector('.cx-detail-body').scrollTop);await drag('.cx-overview-resizer',0,-30);
  check('Resizing does not reset the Preview reading position',await page.evaluate(expected=>Math.abs(document.querySelector('.cx-detail-body').scrollTop-expected)<2,scroll));
  await page.focus('.cx-reader-expand');await page.press('.cx-reader-expand','Enter');await settle();
  check('Expanded reading still covers the whole app and disables background splitters',await page.evaluate(()=>{const app=document.querySelector('.cx-panel').getBoundingClientRect(),detail=document.querySelector('.cx-inspector').getBoundingClientRect();return Math.abs(app.height-detail.height)<3&&document.querySelector('.cx-overview-pane').inert;}));
  await page.press('.cx-detail-body','Escape');await settle();
  const chosen=await size();
  await page.cdp('Emulation.setDeviceMetricsOverride',{width:300,height:400,deviceScaleFactor:1,mobile:true});await settle();
  const narrow=await size();
  check('Small viewport keeps the footer and both height regions in bounds',narrow['.cx-work'].height>0&&narrow['.cx-overview-pane'].height>0&&narrow['.cx-footer'].bottom<=narrow['.cx-panel'].bottom+1);
  check('Narrow detail preserves a visible edge of the list',narrow['.cx-inspector'].width<=narrow['.cx-panel'].width*.9+1);
  await page.press('.cx-inspector-resizer','Enter');
  await page.cdp('Emulation.clearDeviceMetricsOverride');await settle();
  check('Returning to wide viewport restores desired overview size and default detail width',close((await size())['.cx-overview-pane'].height,chosen['.cx-overview-pane'].height)&&close((await size())['.cx-inspector'].width,330));
  await page.press('.cx-overview-resizer','ArrowUp');await page.press('.cx-inspector-resizer','Shift+ArrowLeft');await page.press('.cx-inspector-resizer','Shift+ArrowLeft');await page.press('.cx-inspector-resizer','Shift+ArrowLeft');
  await page.evaluate(()=>{window.readerFixture.setLanguage('zh');document.documentElement.dataset.theme='dark';document.querySelector('.cx-detail-body').scrollTop=0;});await settle();
  await shot('three-resizable-regions');
  await page.cdp('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});await settle();
  await page.press('.cx-overview-resizer','ArrowDown');await settle();
  check('Narrow viewport keeps the vertical splitter usable',await page.evaluate(()=>document.querySelector('.cx-overview-resizer').getBoundingClientRect().width>300&&!document.querySelector('.cx-overview-pane').inert));
  await shot('narrow-resizable-regions');await page.cdp('Emulation.clearDeviceMetricsOverride');
  await writeFile(`${artifactDir}/checks.json`,JSON.stringify(checks,null,2));return checks;
}
